package diaithir.myth;

import com.google.gson.Gson;
import com.google.gson.JsonObject;

import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/** One row of data/diaithir_myth/myth/creatures.json (generated by tools/gen_myth.py). */
public final class Creature {
    public String id, name, court, habitat, preset, upstream, ability;
    public boolean hostile, boss, flyer;
    public int age, weight, xp;
    public double health, attack, speed, flying_speed, knockback_resistance, armor, width, height, follow_range;
    public int egg_primary, egg_secondary;
    public Sounds sounds;

    public static final class Sounds {
        public String ambient, hurt, death;
    }

    private static List<Creature> cache;

    public static Creature byId(String id) {
        for (Creature c : all()) {
            if (c.id.equals(id)) {
                return c;
            }
        }
        throw new IllegalArgumentException(id);
    }

    public static synchronized List<Creature> all() {
        if (cache == null) {
            try (var in = Creature.class.getResourceAsStream("/data/" + DiaithirMyth.MODID + "/myth/creatures.json")) {
                JsonObject root = new Gson().fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), JsonObject.class);
                List<Creature> list = new ArrayList<>();
                Gson gson = new Gson();
                for (var e : root.getAsJsonArray("creatures")) {
                    JsonObject o = e.getAsJsonObject();
                    Creature c = gson.fromJson(o, Creature.class);
                    list.add(c);
                }
                cache = List.copyOf(list);
            } catch (Exception ex) {
                throw new IllegalStateException("cannot read creatures.json", ex);
            }
        }
        return cache;
    }
}
